class Solution {
public:
    int maximumMinimumPath(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        priority_queue<tuple<int, int, int>> pq;
        vector<vector<bool>> seen(m, vector<bool>(n, false));
        pq.emplace(grid[0][0], 0, 0);
        int dr[4] = {1, -1, 0, 0};
        int dc[4] = {0, 0, 1, -1};
        while (!pq.empty()) {
            int score = get<0>(pq.top());
            int r = get<1>(pq.top());
            int c = get<2>(pq.top());
            pq.pop();
            if (seen[r][c]) {
                continue;
            }
            seen[r][c] = true;
            if (r == m - 1 && c == n - 1) {
                return score;
            }
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !seen[nr][nc]) {
                    pq.emplace(min(score, grid[nr][nc]), nr, nc);
                }
            }
        }
        return -1;
    }
};
